/**
 * Deliberate procedural assets: pixel-art PNG sprites and PCM WAV sound effects generated with
 * no third-party files. They are placeholders with clear provenance (license: generated by NEXUS, MIT-compatible).
 */
import { deflateSync } from "node:zlib";

type RGBA = [number, number, number, number];

class Canvas {
  readonly data: Uint8Array;
  constructor(readonly w: number, readonly h: number) {
    this.data = new Uint8Array(w * h * 4);
  }
  set(x: number, y: number, c: RGBA): void {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
    const i = (y * this.w + x) * 4;
    this.data[i] = c[0];
    this.data[i + 1] = c[1];
    this.data[i + 2] = c[2];
    this.data[i + 3] = c[3];
  }
  rect(x: number, y: number, w: number, h: number, c: RGBA): void {
    for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) this.set(xx, yy, c);
  }
  ellipse(cx: number, cy: number, rx: number, ry: number, c: RGBA): void {
    for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++) {
      for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x++) {
        const dx = (x + 0.5 - cx) / rx;
        const dy = (y + 0.5 - cy) / ry;
        if (dx * dx + dy * dy <= 1) this.set(x, y, c);
      }
    }
  }
}

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf: Uint8Array): number {
  let c = 0xffffffff;
  for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff]! ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type: string, data: Uint8Array): Buffer {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const typeBuf = Buffer.from(type, "ascii");
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([typeBuf, Buffer.from(data)])));
  return Buffer.concat([len, typeBuf, Buffer.from(data), crc]);
}

/** Encodes an RGBA canvas as a PNG file. */
export function encodePng(c: Canvas): Buffer {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(c.w, 0);
  ihdr.writeUInt32BE(c.h, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // RGBA
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;
  const raw = Buffer.alloc((c.w * 4 + 1) * c.h);
  for (let y = 0; y < c.h; y++) {
    raw[y * (c.w * 4 + 1)] = 0;
    Buffer.from(c.data.buffer, c.data.byteOffset + y * c.w * 4, c.w * 4).copy(raw, y * (c.w * 4 + 1) + 1);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", new Uint8Array(0)),
  ]);
}

export function playerSprite(): Buffer {
  const c = new Canvas(32, 40);
  c.ellipse(16, 12, 8, 8, [236, 200, 160, 255]); // head
  c.rect(8, 9, 16, 4, [70, 90, 150, 255]); // helmet band
  c.rect(9, 20, 14, 12, [60, 110, 200, 255]); // tunic
  c.rect(6, 21, 4, 10, [60, 110, 200, 255]); // left arm
  c.rect(22, 21, 4, 10, [60, 110, 200, 255]); // right arm
  c.rect(10, 32, 5, 7, [50, 50, 70, 255]); // left leg
  c.rect(17, 32, 5, 7, [50, 50, 70, 255]); // right leg
  c.rect(24, 16, 3, 16, [200, 205, 215, 255]); // sword blade
  c.rect(23, 30, 5, 2, [150, 110, 50, 255]); // hilt
  c.set(13, 12, [30, 30, 40, 255]);
  c.set(19, 12, [30, 30, 40, 255]);
  return encodePng(c);
}

export function slimeSprite(): Buffer {
  const c = new Canvas(32, 32);
  c.ellipse(16, 19, 13, 11, [70, 180, 90, 255]);
  c.ellipse(16, 16, 9, 7, [120, 220, 130, 255]);
  c.ellipse(12, 15, 2, 2.5, [20, 30, 25, 255]);
  c.ellipse(20, 15, 2, 2.5, [20, 30, 25, 255]);
  c.rect(11, 22, 10, 2, [30, 80, 40, 255]);
  return encodePng(c);
}

export function floorTile(): Buffer {
  const c = new Canvas(32, 32);
  c.rect(0, 0, 32, 32, [34, 40, 58, 255]);
  for (let i = 0; i < 32; i += 16) {
    c.rect(0, i, 32, 1, [28, 33, 48, 255]);
    c.rect(i, 0, 1, 32, [28, 33, 48, 255]);
  }
  c.rect(2, 2, 3, 3, [44, 52, 74, 255]);
  c.rect(20, 18, 3, 3, [44, 52, 74, 255]);
  return encodePng(c);
}

export function wallTile(): Buffer {
  const c = new Canvas(32, 32);
  c.rect(0, 0, 32, 32, [70, 66, 92, 255]);
  c.rect(0, 0, 32, 3, [104, 98, 130, 255]);
  c.rect(0, 15, 32, 2, [52, 49, 70, 255]);
  c.rect(14, 3, 2, 12, [52, 49, 70, 255]);
  c.rect(6, 17, 2, 15, [52, 49, 70, 255]);
  return encodePng(c);
}

export function heartIcon(): Buffer {
  const c = new Canvas(16, 16);
  c.ellipse(5, 6, 4, 4, [230, 70, 90, 255]);
  c.ellipse(11, 6, 4, 4, [230, 70, 90, 255]);
  for (let y = 8; y < 15; y++) {
    const half = 7 - (y - 8);
    c.rect(8 - half, y, half * 2 + 1 > 0 ? half * 2 : 0, 1, [230, 70, 90, 255]);
  }
  return encodePng(c);
}

/** Mono 16-bit PCM WAV. */
export function encodeWav(samples: Float32Array, sampleRate = 22050): Buffer {
  const dataLen = samples.length * 2;
  const buf = Buffer.alloc(44 + dataLen);
  buf.write("RIFF", 0);
  buf.writeUInt32LE(36 + dataLen, 4);
  buf.write("WAVE", 8);
  buf.write("fmt ", 12);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20);
  buf.writeUInt16LE(1, 22);
  buf.writeUInt32LE(sampleRate, 24);
  buf.writeUInt32LE(sampleRate * 2, 28);
  buf.writeUInt16LE(2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write("data", 36);
  buf.writeUInt32LE(dataLen, 40);
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]!));
    buf.writeInt16LE(Math.round(s * 32767), 44 + i * 2);
  }
  return buf;
}

const RATE = 22050;

function synth(seconds: number, fn: (t: number) => number): Float32Array {
  const n = Math.floor(seconds * RATE);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) out[i] = fn(i / RATE);
  return out;
}

let seed = 1337;
function noise(): number {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff * 2 - 1;
}

export function sfxHit(): Buffer {
  return encodeWav(synth(0.18, (t) => noise() * Math.exp(-t * 28) * 0.8 + Math.sin(2 * Math.PI * (180 - t * 400) * t) * Math.exp(-t * 18) * 0.5));
}
export function sfxSwing(): Buffer {
  return encodeWav(synth(0.16, (t) => Math.sin(2 * Math.PI * (700 - t * 2800) * t) * Math.exp(-t * 16) * 0.35 + noise() * Math.exp(-t * 40) * 0.2));
}
export function sfxPickup(): Buffer {
  return encodeWav(synth(0.25, (t) => (t < 0.12 ? Math.sin(2 * Math.PI * 880 * t) : Math.sin(2 * Math.PI * 1320 * t)) * Math.exp(-t * 9) * 0.4));
}
export function sfxDeath(): Buffer {
  return encodeWav(synth(0.5, (t) => Math.sin(2 * Math.PI * (320 - t * 500) * t) * Math.exp(-t * 5) * 0.45));
}
export function sfxWin(): Buffer {
  const notes = [523.25, 659.25, 783.99, 1046.5];
  return encodeWav(synth(0.9, (t) => {
    const idx = Math.min(notes.length - 1, Math.floor(t / 0.2));
    return Math.sin(2 * Math.PI * notes[idx]! * t) * Math.exp(-((t % 0.2) * 9)) * 0.4;
  }));
}
export function sfxDamage(): Buffer {
  return encodeWav(synth(0.22, (t) => Math.sin(2 * Math.PI * (240 - t * 600) * t) * Math.exp(-t * 12) * 0.5));
}

/** 8-second looping chiptune-style background track. */
export function musicLoop(): Buffer {
  const bpm = 120;
  const beat = 60 / bpm;
  const melody = [220, 262, 294, 262, 220, 196, 220, 262, 330, 294, 262, 220, 196, 175, 196, 220];
  const bass = [110, 110, 98, 98, 87, 87, 98, 98];
  const total = 8;
  return encodeWav(
    synth(total, (t) => {
      const step = Math.floor(t / (beat / 2)) % melody.length;
      const f = melody[step]!;
      const local = (t % (beat / 2)) / (beat / 2);
      const lead = (Math.sign(Math.sin(2 * Math.PI * f * t)) * 0.12) * (1 - local * 0.6);
      const bstep = Math.floor(t / beat) % bass.length;
      const b = Math.sin(2 * Math.PI * bass[bstep]! * t) * 0.18;
      const env = Math.min(1, t * 8, (total - t) * 8);
      return (lead + b) * env;
    }),
    RATE,
  );
}
